"use client"

// ShaderBackground — generated by the 21st.dev Shader Builder
// ("Waves"). Zero dependencies: one WebGL
// canvas that fills its parent. Drop it behind your content with
// <div className="relative"><ShaderBackground className="absolute inset-0" />…

import { useEffect, useRef } from "react"

const VERT = `attribute vec2 a_position;
void main() {
  gl_Position = vec4(a_position, 0.0, 1.0);
}`

const FRAG = `#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform vec3 u_colors[8];
// Eight packed vectors + eight colour vectors fit WebGL1's guaranteed
// minimum of 16 fragment uniform vectors. Macros preserve the public u_* API.
uniform vec4 u_scene;      // resolution.xy, time, colour count
uniform vec4 u_shape;      // scale, intensity, paramA, warp
uniform vec4 u_surface;    // detail, contrast, brightness, saturation
uniform vec4 u_finish;     // hue, vignette, blur, grain
uniform vec4 u_transform;  // seed, rotation, drift, OKLab toggle
uniform vec4 u_space;      // offset.xy, pointer.xy
uniform vec4 u_cursor;
uniform vec4 u_readability; // content boundary, content blend, surrounding blend, meta height

#define u_resolution u_scene.xy
#define u_time u_scene.z
#define u_colorCount u_scene.w
#define u_scale u_shape.x
#define u_intensity u_shape.y
#define u_paramA u_shape.z
#define u_warp u_shape.w
#define u_detail u_surface.x
#define u_contrast u_surface.y
#define u_brightness u_surface.z
#define u_saturation u_surface.w
#define u_hue u_finish.x
#define u_vignette u_finish.y
#define u_blur u_finish.z
#define u_grain u_finish.w
#ifdef GL_FRAGMENT_PRECISION_HIGH
#define u_seed u_transform.x
#else
// Keep hash inputs inside mediump's guaranteed ±2^14 range.
#define u_seed mod(u_transform.x, 31.0)
#endif
#define u_rotate u_transform.y
#define u_drift u_transform.z
#define u_oklab u_transform.w
#define u_offset u_space.xy
#define u_mouse u_space.zw
#define u_cursorPresence u_cursor.x
#define u_cursorEffect u_cursor.y
#define u_cursorStrength u_cursor.z
#define u_cursorRadius u_cursor.w

float hash21(vec2 p) {
#ifndef GL_FRAGMENT_PRECISION_HIGH
  p = mod(p, 31.0);
#endif
  p = fract(p * vec2(234.34, 435.345));
  p += dot(p, p + 34.23);
  return fract(p.x * p.y);
}

// Even, un-structured white noise for film grain (Dave Hoskins hash12). The
// multiply hash above is fine for value noise but shows a faint axis-aligned
// mesh at integer fragment coords, which reads as a net over flat areas.
float grainHash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
#ifndef GL_FRAGMENT_PRECISION_HIGH
  p = mod(p, 31.0);
#endif
  float n = sin(dot(p, vec2(41.0, 289.0)));
  return fract(vec2(15731.743, 7892.321) * n);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash21(i), hash21(i + vec2(1.0, 0.0)), u.x),
    mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), u.x),
    u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = p * 2.03 + vec2(17.0, 9.2);
    a *= 0.5;
  }
  return v;
}

// --- OKLab colour mixing (perceptual), gated by u_oklab -----------------------
vec3 srgbToLinear(vec3 c) {
  return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)),
    step(0.04045, c));
}
vec3 linearToSrgb(vec3 c) {
  // max() guards the sRGB branch: out-of-gamut OKLab interpolations can send a
  // channel negative, and pow(negative, …) is NaN which mix()/step() would
  // then propagate. The linear branch clips such channels to 0 downstream.
  return mix(c * 12.92, 1.055 * pow(max(c, vec3(0.0)), vec3(1.0 / 2.4)) - 0.055,
    step(0.0031308, c));
}
vec3 linToOklab(vec3 c) {
  float l = 0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b;
  float m = 0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b;
  float s = 0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b;
  l = pow(max(l, 0.0), 1.0 / 3.0);
  m = pow(max(m, 0.0), 1.0 / 3.0);
  s = pow(max(s, 0.0), 1.0 / 3.0);
  return vec3(
    0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
    1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
    0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s);
}
vec3 oklabToLin(vec3 c) {
  float l = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
  float m = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
  float s = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;
  l = l * l * l; m = m * m * m; s = s * s * s;
  return vec3(
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s);
}
vec3 mixColour(vec3 a, vec3 b, float t) {
  if (u_oklab > 0.5) {
    vec3 la = linToOklab(srgbToLinear(a));
    vec3 lb = linToOklab(srgbToLinear(b));
    return clamp(linearToSrgb(oklabToLin(mix(la, lb, t))), 0.0, 1.0);
  }
  return mix(a, b, t);
}

// Mix through the recipe colours; x is clamped to 0..1. WebGL1 forbids
// dynamic uniform indexing in fragment shaders, hence the constant loop.
vec3 palette(float x) {
  float n = max(u_colorCount - 1.0, 1.0);
  float f = clamp(x, 0.0, 1.0) * n;
  vec3 col = u_colors[0];
  for (int i = 0; i < 7; i++) {
    if (float(i) < n)
      col = mixColour(col, u_colors[i + 1],
        smoothstep(0.0, 1.0, clamp(f - float(i), 0.0, 1.0)));
  }
  return col;
}

vec3 hueRotate(vec3 col, float a) {
  const mat3 toYIQ = mat3(0.299, 0.596, 0.211,
                          0.587, -0.274, -0.523,
                          0.114, -0.322, 0.312);
  const mat3 toRGB = mat3(1.0, 1.0, 1.0,
                          0.956, -0.272, -1.106,
                          0.621, -0.647, 1.703);
  vec3 yiq = toYIQ * col;
  float ca = cos(a), sa = sin(a);
  yiq = vec3(yiq.x, yiq.y * ca - yiq.z * sa, yiq.y * sa + yiq.z * ca);
  return toRGB * yiq;
}

vec3 shade(vec2 uv, vec2 p, float t) {
  // Keep both edges inside the palette so the meta strip and upper hero
  // retain moving blue forms instead of clamping to a flat endpoint colour.
  float y = 0.16 + uv.y * 0.68
    + sin(uv.x * (3.0 + u_intensity * 9.0) + t) * 0.16
    + sin(uv.y * 4.4 - uv.x * 2.6 + t * 0.65) * 0.055
    + (fbm(p * 2.0 + t * 0.1) - 0.5) * u_intensity * 0.6;
  return palette(y);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution.xy;
  vec2 screenUv = uv;
  vec2 p = (gl_FragCoord.xy - 0.5 * u_resolution.xy)
    / min(u_resolution.x, u_resolution.y);
  float cursorMask = 0.0;

  // Cursor modes 1–3 are local distortions. Push shifts the same screen-space
  // coordinates before field transforms, so Zoom/Rotate don't change its feel.
  if (u_cursorPresence > 0.001) {
    // u_mouse is normalized to -1..1 in canvas space. Convert it to the same
    // aspect-corrected screen space as p so effects stay under the cursor.
    vec2 cursor = (0.5 * u_mouse * u_resolution.xy)
      / min(u_resolution.x, u_resolution.y);
    vec2 cursorDelta = p - cursor;
    if (u_cursorEffect < 0.5) {
      p += cursor * u_cursorPresence * u_cursorStrength * 0.55;
    } else {
      float cursorDistance = length(cursorDelta);
      vec2 cursorDirection = cursorDelta / max(cursorDistance, 0.0001);
      cursorMask = u_cursorPresence
        * (1.0 - smoothstep(0.0, u_cursorRadius, cursorDistance));
      if (u_cursorEffect < 1.5) {
        p -= cursorDirection * cursorMask * u_cursorStrength * 0.24;
      } else if (u_cursorEffect < 2.5) {
        float cursorAngle = cursorMask * u_cursorStrength * 2.2;
        float cc = cos(cursorAngle), cs = sin(cursorAngle);
        p = cursor + mat2(cc, -cs, cs, cc) * cursorDelta;
      } else if (u_cursorEffect < 3.5) {
        float ripple = sin(
          cursorDistance / max(u_cursorRadius, 0.001) * 18.0 - u_time * 5.0);
        p -= cursorDirection * ripple * cursorMask * u_cursorStrength * 0.07;
      }
    }
  }

  // Keep presets that read uv (rather than p) in the same warped space.
  uv = p * min(u_resolution.x, u_resolution.y) / u_resolution.xy + 0.5;
  p *= u_scale;
  // Field transform: rotate, pan, pointer push, slow drift.
  if (abs(u_rotate) > 0.0001) {
    float cr = cos(u_rotate), sr = sin(u_rotate);
    p = mat2(cr, -sr, sr, cr) * p;
  }
  p += u_offset;
  if (u_drift > 0.0001)
    p += u_drift * vec2(sin(u_time * 0.31), cos(u_time * 0.23));
  // Organic domain warp.
  if (u_warp > 0.0) {
    p += u_warp * (vec2(
      fbm(p * u_detail + u_seed),
      fbm(p * u_detail + vec2(5.2, 1.3))) - 0.5);
  }
  // Shade, with an optional soft 5-tap blur.
  vec3 col;
  if (u_blur > 0.0) {
    float e = u_blur;
    float pe = e * u_scale;
    vec2 uvE = vec2(e) * min(u_resolution.x, u_resolution.y) / u_resolution.xy;
    col  = shade(uv, p, u_time) * 0.36;
    col += shade(uv + vec2(uvE.x, 0.0), p + vec2(pe, 0.0), u_time) * 0.16;
    col += shade(uv - vec2(uvE.x, 0.0), p - vec2(pe, 0.0), u_time) * 0.16;
    col += shade(uv + vec2(0.0, uvE.y), p + vec2(0.0, pe), u_time) * 0.16;
    col += shade(uv - vec2(0.0, uvE.y), p - vec2(0.0, pe), u_time) * 0.16;
  } else {
    col = shade(uv, p, u_time);
  }
  // Post: contrast, saturation, hue, brightness, vignette, grain.
  if (abs(u_contrast - 1.0) > 0.0001)
    col = (col - 0.5) * u_contrast + 0.5;
  if (abs(u_saturation - 1.0) > 0.0001) {
    float luma = dot(col, vec3(0.299, 0.587, 0.114));
    col = mix(vec3(luma), col, u_saturation);
  }
  if (abs(u_hue) > 0.0001)
    col = hueRotate(col, u_hue);
  if (abs(u_brightness) > 0.0001)
    col += u_brightness;
  if (u_vignette > 0.0001) {
    float vd = length(screenUv - 0.5) * 1.41421356;
    col *= 1.0 - u_vignette * smoothstep(0.35, 1.0, vd);
  }
  if (u_cursorPresence > 0.001 && u_cursorEffect > 3.5)
    col += (vec3(0.18) + col * 0.12) * cursorMask * u_cursorStrength;
  if (u_grain > 0.0001)
    col += (grainHash(
      gl_FragCoord.xy + vec2(u_seed * 17.0, u_seed * 31.0)) - 0.5) * u_grain;
  // Keep waves visible everywhere. The text area uses a lighter blue colour
  // blend; the photograph surroundings receive stronger brand-blue waves.
  // This changes colour strength, never canvas alpha or a bottom opacity mask.
  float contentMask = smoothstep(u_readability.x - 0.24, u_readability.x, screenUv.y);
  // Protect the small meta text with the same moving colour field, without
  // introducing a separate panel, canvas, or opacity fade at the bottom.
  float metaMask = 1.0 - smoothstep(u_readability.w, u_readability.w + 0.12, screenUv.y);
  float colourStrength = mix(u_readability.z, u_readability.y, contentMask);
  colourStrength = mix(colourStrength, 0.48, metaMask);
  vec3 lightBlueBase = vec3(0.72549020, 0.83137255, 0.90980392);
  col = mix(lightBlueBase, clamp(col, 0.0, 1.0), colourStrength);
  // Lift only darker colours behind text. Linear-light blending sets a
  // predictable contrast floor while retaining the travelling blue field.
  vec3 linearColour = srgbToLinear(col);
  vec3 readableBlue = srgbToLinear(vec3(0.76470588, 0.88627451, 0.98039216));
  float luminance = dot(linearColour, vec3(0.2126, 0.7152, 0.0722));
  float blueLuminance = dot(readableBlue, vec3(0.2126, 0.7152, 0.0722));
  float readabilityLift = clamp((0.60 - luminance) / max(blueLuminance - luminance, 0.001), 0.0, 1.0);
  vec3 readableColour = linearToSrgb(mix(linearColour, readableBlue, readabilityLift));
  // A broad travelling light wave retains visible variation where the
  // contrast floor would otherwise flatten several darker palette colours.
  float lightWave = smoothstep(-0.8, 0.9, sin(uv.x * 5.8 + uv.y * 3.4 + u_time));
  readableColour = mix(readableColour, linearToSrgb(readableBlue), lightWave * 0.65);
  col = mix(col, readableColour, max(contentMask, metaMask));
  gl_FragColor = vec4(col, 1.0);
}
`

// Adapted from the supplied 21st.dev Waves preset. The shader blends this palette
// into a cool-blue base so navy never becomes a dark background for the copy.
const COLORS = ['#b9d4e8', '#78aed2', '#3d7faa', '#1d5278', '#b9d4e8'];
const RGB_COLORS = COLORS.flatMap((hex) => [1, 3, 5].map((offset) => parseInt(hex.slice(offset, offset + 2), 16) / 255));
const WAVES = {
  timeScale: -1.60,
  intensity: 0.50,
  warp: 0.08,
  drift: 0.26,
  grain: 0.006,
};
const pendingContextReleases = new WeakMap<HTMLCanvasElement, number>();

function createRenderer(canvas: HTMLCanvasElement, animate = true): (releaseContext?: boolean) => void {
  const pendingRelease = pendingContextReleases.get(canvas);
  if (pendingRelease !== undefined) window.clearTimeout(pendingRelease);
  pendingContextReleases.delete(canvas);
  canvas.dataset.state = 'fallback';
  const context = canvas.getContext('webgl', { antialias: false, alpha: false, depth: false, stencil: false });
  if (!context) return () => {};
  const gl = context;

  const compile = (type: number, source: string) => {
    const shader = gl.createShader(type);
    if (!shader) return null;
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      gl.deleteShader(shader);
      return null;
    }
    return shader;
  };
  const vertex = compile(gl.VERTEX_SHADER, VERT);
  const fragment = compile(gl.FRAGMENT_SHADER, FRAG);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) {
    if (vertex) gl.deleteShader(vertex);
    if (fragment) gl.deleteShader(fragment);
    if (program) gl.deleteProgram(program);
    return () => {};
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return () => {};
  }
  const buffer = gl.createBuffer();
  if (!buffer) {
    gl.deleteProgram(program);
    return () => {};
  }
  gl.useProgram(program);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const position = gl.getAttribLocation(program, 'a_position');
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

  const uniform = (name: string) => gl.getUniformLocation(program, name);
  const scene = uniform('u_scene');
  const readability = uniform('u_readability');
  gl.uniform3fv(uniform('u_colors[0]'), new Float32Array(RGB_COLORS.concat(Array(9).fill(0))));
  gl.uniform4f(uniform('u_shape'), 2, WAVES.intensity, 0.47, WAVES.warp);
  gl.uniform4f(uniform('u_surface'), 1.536, 1.02, 0, 1.05);
  // No vignette or five-tap blur: the atmosphere should stay light and inexpensive.
  gl.uniform4f(uniform('u_finish'), 0, 0, 0, WAVES.grain);
  gl.uniform4f(uniform('u_transform'), 4012, 5.6549, WAVES.drift, 0);
  gl.uniform4f(uniform('u_space'), 0.11, -0.19, 0, 0);
  gl.uniform4f(uniform('u_cursor'), 0, 2, 0.65, 0.46);

  let disposed = false;
  let visible = document.visibilityState === 'visible';
  let inView = false;
  let frame = 0;
  let lastDraw: number | null = null;
  let elapsed = 0;
  let bounds = canvas.getBoundingClientRect();
  const introduction = canvas.closest('.hero-section')?.querySelector('.hero-intro');
  const meta = canvas.closest('.hero-section')?.querySelector('.hero-meta');
  const resize = () => {
    const contentHeight = introduction ? introduction.getBoundingClientRect().height + 24 : bounds.height;
    const contentBoundary = 1 - Math.min(1, contentHeight / Math.max(1, bounds.height));
    const metaHeight = (meta?.getBoundingClientRect().height ?? 0) / Math.max(1, bounds.height);
    gl.uniform4f(readability, contentBoundary, 0.38, 0.78, metaHeight);
    // Decorative output needs neither retina resolution nor full-screen GPU cost.
    const pixelScale = Math.min(1, Math.sqrt(600_000 / Math.max(1, bounds.width * bounds.height)));
    const width = Math.max(1, Math.round(bounds.width * pixelScale));
    const height = Math.max(1, Math.round(bounds.height * pixelScale));
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
      gl.viewport(0, 0, width, height);
    }
  };
  const requestRender = () => {
    if (!disposed && visible && inView && frame === 0) frame = requestAnimationFrame(render);
  };
  const pause = () => {
    cancelAnimationFrame(frame);
    frame = 0;
    lastDraw = null;
    canvas.dataset.state = 'paused';
  };
  function render(now: number) {
    frame = 0;
    if (disposed || !visible || !inView) return;
    // Cap actual GPU draws at 30 fps, including on 120/144 Hz displays.
    if (lastDraw !== null && now - lastDraw < 1000 / 30) {
      requestRender();
      return;
    }
    if (animate && lastDraw !== null) elapsed += Math.min((now - lastDraw) / 1000, 0.1);
    lastDraw = now;
    gl.uniform4f(scene, canvas.width, canvas.height, elapsed * WAVES.timeScale, COLORS.length);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    canvas.dataset.state = animate ? 'running' : 'static';
    if (animate) requestRender();
  }
  const resizeObserver = new ResizeObserver(() => {
    bounds = canvas.getBoundingClientRect();
    resize();
    requestRender();
  });
  resizeObserver.observe(canvas);
  if (introduction) resizeObserver.observe(introduction);
  if (meta) resizeObserver.observe(meta);
  const intersectionObserver = new IntersectionObserver(([entry]) => {
    inView = entry?.isIntersecting ?? false;
    if (inView) requestRender();
    else pause();
  });
  intersectionObserver.observe(canvas);
  const onVisibilityChange = () => {
    visible = document.visibilityState === 'visible';
    if (visible) requestRender();
    else pause();
  };
  document.addEventListener('visibilitychange', onVisibilityChange);
  resize();

  return (releaseContext = true) => {
    if (disposed) return;
    disposed = true;
    cancelAnimationFrame(frame);
    resizeObserver.disconnect();
    intersectionObserver.disconnect();
    document.removeEventListener('visibilitychange', onVisibilityChange);
    gl.deleteBuffer(buffer);
    gl.deleteProgram(program);
    if (releaseContext) {
      // Delaying context release lets React Strict Mode reuse it on its second setup.
      const timer = window.setTimeout(() => {
        if (pendingContextReleases.get(canvas) !== timer) return;
        pendingContextReleases.delete(canvas);
        gl.getExtension('WEBGL_lose_context')?.loseContext();
      }, 0);
      pendingContextReleases.set(canvas, timer);
    }
  };
}

export function ShaderBackground({ className }: { className?: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const motionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');
    let stop: (releaseContext?: boolean) => void = () => {};
    const start = () => {
      // Preference changes release GPU resources but keep the canvas context
      // available for visitors who turn animation back on without reloading.
      stop(false);
      stop = () => {};
      // Reduced motion draws the identical shader once at time zero, then
      // redraws only when needed for resizing or visibility, without a loop.
      stop = createRenderer(canvas, !motionPreference.matches);
    };
    const onContextLost = (event: Event) => {
      event.preventDefault();
      stop(false);
      stop = () => {};
      canvas.dataset.state = 'fallback';
    };
    motionPreference.addEventListener('change', start);
    canvas.addEventListener('webglcontextlost', onContextLost);
    canvas.addEventListener('webglcontextrestored', start);
    start();
    return () => {
      motionPreference.removeEventListener('change', start);
      canvas.removeEventListener('webglcontextlost', onContextLost);
      canvas.removeEventListener('webglcontextrestored', start);
      stop();
    };
  }, []);

  return <canvas ref={canvasRef} className={className} aria-hidden="true" data-state="fallback" style={{ display: 'block', width: '100%', height: '100%' }} />;
}

